let apiPromise;
function youtubeAPI(){if(window.YT?.Player)return Promise.resolve(window.YT);if(!apiPromise)apiPromise=new Promise((resolve,reject)=>{const previous=window.onYouTubeIframeAPIReady,script=document.createElement('script'),timer=setTimeout(()=>reject(Error('YouTube did not respond. Check your connection and try again.')),18000);window.onYouTubeIframeAPIReady=()=>{clearTimeout(timer);previous?.();resolve(window.YT);};script.src='https://www.youtube.com/iframe_api';script.onerror=()=>{clearTimeout(timer);reject(Error('YouTube could not load on this connection.'));};document.head.append(script);});return apiPromise;}
const errors={2:'YouTube could not recognise this video.',5:'This video could not play in this browser.',100:'This video is private or no longer available.',101:'The owner has disabled embedded playback.',150:'The owner has disabled embedded playback.',153:'YouTube did not receive the required player identification.'};
export async function createPlayer(config,onChange,{signal}={}){let player,state='loading',error=null,ready=false,active=!signal?.aborted;const emit=()=>{if(active&&!signal?.aborted)onChange({state,error,ready,source:'youtube-iframe-api',videoId:config.videoId});};
 const destroy=()=>{active=false;ready=false;try{player?.destroy();}catch{};};signal?.addEventListener('abort',destroy,{once:true});emit();
 const controller={snapshot:()=>({state,error,ready,source:'youtube-iframe-api',videoId:config.videoId,currentTime:ready?player?.getCurrentTime?.():null,duration:ready?player?.getDuration?.():null}),play(){if(!active||!ready)return false;try{player.playVideo();return true;}catch{return false;}},stop(){try{player?.stopVideo?.();}catch{}},destroy};
 try{const YT=await youtubeAPI();if(!active||signal?.aborted)return controller;player=new YT.Player('youtube-player',{width:'100%',height:'100%',videoId:config.videoId,playerVars:{autoplay:0,controls:1,playsinline:1,rel:0,origin:location.origin},events:{onReady(){if(!active)return;ready=true;state='ready';const iframe=player.getIframe();iframe.title=config.creator+' — '+config.title;iframe.referrerPolicy='strict-origin-when-cross-origin';emit();},onStateChange(event){if(!active)return;state=({[-1]:'unstarted',0:'ended',1:'playing',2:'paused',3:'buffering',5:'cued'})[event.data]||'unknown';error=null;emit();},onError(event){state='error';error=errors[event.data]||'YouTube could not play this video ('+event.data+').';emit();},onAutoplayBlocked(){state='awaiting-gesture';emit();}}});}catch(e){state='error';error=e.message;emit();}
 return controller;
}
